hunks.old:
# All newly integrated reader/Find and trust modules remain whole-module strict gates.
# The actual Windows run completed this suite alone in 208 seconds;
# another run reached its unchanged 600-second bound alongside other suites.
$academicSuite = 'tests/research/test_academic_library.py'
$parallelSuites = @($suites | Where-Object { $_ -cne $academicSuite })
$academicExit = 0
if ($suites -ccontains $academicSuite) {
  if ($parallelSuites.Count + 1 -ne $suites.Count) { throw 'Required academic suite must occur exactly once.' }
  & $env:CARR_PYTHON scripts/ci_check.py --jobs 1 $academicSuite 2>&1 | Tee-Object 'ci-results/integrated-tests.txt'
  $academicExit = $LASTEXITCODE
} elseif ($parallelSuites.Count -ne $suites.Count) {
  throw 'A different shard must own the complete academic suite.'
}
$parallelArguments = @('--jobs', '3')
if ($parallelSuites -ccontains 'tests/transcription/test_admission_boundaries.py') {
  $parallelArguments += @('--suite-timeout', 'tests/transcription/test_admission_boundaries.py=900')
}
& $env:CARR_PYTHON scripts/ci_check.py @parallelArguments @parallelSuites 2>&1 | Tee-Object -Append 'ci-results/integrated-tests.txt'
$parallelExit = $LASTEXITCODE
if ($academicExit -ne 0 -or $parallelExit -ne 0) { throw 'Required whole source suites failed.' }

hunks.replacement:
# Keep the two observed heavy wholes separate from the remaining pool.
# Each real group retains its own strict ci_check aggregate and600-second children.
$completionUnique = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
foreach ($suite in $completionSuites) {
  if (-not $completionUnique.Add($suite)) { throw 'A required completion suite is duplicated.' }
}
$isolatedCompletionNames = @(
  'tests/studio/test_book_batch.py',
  'tests/audio/test_voice_package_management.py'
)
$isolatedCompletionSuites = @($completionSuites | Where-Object { $isolatedCompletionNames -ccontains $_ })
$parallelCompletionSuites = @($completionSuites | Where-Object { $isolatedCompletionNames -cnotcontains $_ })
if ($completionSuites.Count -ne 185 -or $isolatedCompletionSuites.Count -ne 2 -or $parallelCompletionSuites.Count -ne 183) { throw 'The complete185-suite source groups differ from review.' }
Write-Output ('Reviewed isolated completion suites: ' + ($isolatedCompletionSuites -join ', '))
$PSNativeCommandUseErrorActionPreference = $false
& $env:CARR_COMPLETION_PYTHON scripts/ci_check.py --jobs 1 @isolatedCompletionSuites 2>&1 | Tee-Object 'ci-completion-results/source-regressions.txt'
$isolatedCompletionExit = $LASTEXITCODE
& $env:CARR_COMPLETION_PYTHON scripts/ci_check.py --jobs 3 @parallelCompletionSuites 2>&1 | Tee-Object -Append 'ci-completion-results/source-regressions.txt'
$parallelCompletionExit = $LASTEXITCODE
if ($isolatedCompletionExit -ne 0 -or $parallelCompletionExit -ne 0) { throw 'Required whole completion source suites failed.' }

foreach ($groupCount in @($isolatedCompletionSuites.Count, $parallelCompletionSuites.Count)) {
  $summary = 'Required suites complete: ' + $groupCount + '; passed=' + $groupCount + '; failed=0'
  $pattern = '^' + [regex]::Escape($summary) + '$'
  if (@(Select-String -LiteralPath 'ci-completion-results/source-regressions.txt' -Pattern $pattern).Count -ne 1) { throw 'A real completion group lacks its exact complete summary.' }
}
